window.kbPageData["views/entry/k-c2383a4ccfc99a5b"] = {"key":"entry/k-c2383a4ccfc99a5b","state":{"route":"entry/k-c2383a4ccfc99a5b"},"node":{"id":"k-c2383a4ccfc99a5b","mode":"k","title":"法治政府建设","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#93","政治理论必刷100题#94","政治理论必刷100题#95","政治理论必刷100题#96","江苏 2024 B类 申论#4"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":5,"tags":{"专题":["law"],"主类":["制度与规则"],"出处性质":["专项题干","专项题解析","机构注释"],"学科":["法律"],"来源主题":["发展与治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"法治政府建设是推动各级政府依法履行职能，将行政权力的配置、行使和监督纳入法治轨道的建设任务。党的二十大报告将其定位为全面依法治国的重点任务和主体工程。","review":{"title":"法治政府建设","type":"制度与规则","definition":"法治政府建设是推动各级政府依法履行职能，将行政权力的配置、行使和监督纳入法治轨道的建设任务。党的二十大报告将其定位为全面依法治国的重点任务和主体工程。","explanation":"推进政府机构、职能、权限、程序和责任法定化，可以明确行政机关的职责和权限。重大行政决策应履行法定程序，行政执法应当有法定依据，行政权力行使应当接受监督。","basis":"据关联原题及所列出处编释。","references":[{"source":"govlaw","location":"纲要开篇·建设定位"}],"related":["k-469f06bedb2b5a5f","k-e69dd9ac0a8d9123"],"domain":"法律","examFocus":{"政治理论必刷100题#93":"对照党的二十大报告，区分依法执政、立法、法治政府建设和公正司法的定位与要求。","政治理论必刷100题#94":"在习近平法治思想相关表述中，区分法治队伍建设、法治监督体系和法治政府建设各自的要求。","政治理论必刷100题#95":"依据党的二十大报告区分法治政府与法治社会的定位，并核对司法和公共法律服务的要求。","政治理论必刷100题#96":"把领导干部的带头要求、党的领导、法治政府建设和指导思想的表述放回全面依法治国的部署中核对。","江苏 2024 B类 申论#4":"结合给定资料7和执法案例，辨析“加分”与“乘效”分别涉及哪些执法手段、运行条件和成效。"}},"aspects":[{"title":"在全面依法治国中的定位","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。C项关于扎实推进依法行政和法治政府建设定位的表述正确。答案为A，错在把党的二十大报告所说的“宪法确定”写成“党章确定”。","evidence":"扎实推进依法行政，法治政府建设是全面依法治国的重点任务和主体工程","qids":["政治理论必刷100题#93"]},{"unit":"Q2","role":"直接考查","use":"本题要求选出关于习近平法治思想的不正确表述。D项符合《法治政府建设实施纲要（2021—2025年）》对法治政府建设的定位。答案为A，高素质法治队伍应强调德才兼备。","evidence":"法治政府建设是全面依法治国的重点任务和主体工程","qids":["政治理论必刷100题#94"]},{"unit":"Q3","role":"直接考查","use":"本题要求选出正确表述。②把法治政府建设的定位套用于法治社会建设。党的二十大报告将法治社会定位为构筑法治国家的基础，因此排除②，选B（①③④）。","evidence":"②法治社会建设是全面依法治国的重点任务和主体工程","qids":["政治理论必刷100题#95"]},{"unit":"Q4","role":"直接考查","use":"本题的③对应2020年中央全面依法治国工作会议关于系统谋划、推动法治政府建设率先突破的部署。③成立，四项表述均正确，选D。","evidence":"③全面依法治国是一个系统工程，法治政府建设是重点任务和主体工程","qids":["政治理论必刷100题#96"]}]},{"title":"行政执法规范化与效能提升","uses":[{"unit":"Q5","role":"解题依据","use":"本题要求阐释智慧执法与执法创新。给定资料7以《提升行政执法质量三年行动计划（2023—2025年）》为背景，将执法质量和效能与群众切身利益相联系，并把健全执法机构运行规范、提升人员素质作为科技赋能的基础。其他材料中的行政行为码和裁量基准分别提供了执法过程可追溯和统一处罚尺度的实例。","evidence":"行政执法是法治政府建设的“最后一公里”。","qids":["江苏 2024 B类 申论#4"]}]}],"sources":[{"id":"dc297c735547bdb5","label":"法治政府建设","topic":"发展与治理","category":"非时政","text":"1.法治政府建设\n我们要坚持走中国特色社会主义法治道路，建设中国特色社会主义法治体系、建设社会\n主义法治国家，围绕保障和促进社会公平正义，坚持依法治国、依法执政、依法行政共同推\n进，坚持法治国家、法治政府、法治社会一体建设，全面推进科学立法、严格执法、公正司\n法、全民守法，全面推进国家各方面工作法治化。\n扎实推进依法行政。法治政府建设是全面依法治国的重点任务和主体工程。\n——《党的二十大报告》","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":52,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#93":{"paper":"政治理论必刷100题","n":93,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",28],"asrc":["国省考政治理论必刷100题.pdf",92],"card":"a60b4e68b5f23d3ca988bb6b","links":[{"id":"k-c2383a4ccfc99a5b","role":"直接考查","why":"法治政府建设在全面依法治国中的定位是该项的实质内容。"}]},"政治理论必刷100题#94":{"paper":"政治理论必刷100题","n":94,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",28],"asrc":["国省考政治理论必刷100题.pdf",92],"card":"5847a63f7dd0a1295a26f337","links":[{"id":"k-c2383a4ccfc99a5b","role":"直接考查","why":"题目核对法治政府建设在全面依法治国中的定位。"}]},"政治理论必刷100题#95":{"paper":"政治理论必刷100题","n":95,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",29],"asrc":["国省考政治理论必刷100题.pdf",93],"card":"5847a63f7dd0a1295a26f337","links":[{"id":"k-c2383a4ccfc99a5b","role":"直接考查","why":"须确认全面依法治国的重点任务和主体工程对应法治政府建设。"}]},"政治理论必刷100题#96":{"paper":"政治理论必刷100题","n":96,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",29],"asrc":["国省考政治理论必刷100题.pdf",93],"card":"5847a63f7dd0a1295a26f337","links":[{"id":"k-c2383a4ccfc99a5b","role":"直接考查","why":"第三项考查法治政府建设在全面依法治国系统工程中的定位。"}]},"江苏 2024 B类 申论#4":{"paper":"江苏 2024 B类 申论","n":4,"mod":"申论","src":["bed85ff950924671a40c.pdf",4],"asrc":["f75bd8f3e117a96a77ba.pdf",3],"card":"57c5c7412f0e0a939f508862","links":[{"id":"k-c2383a4ccfc99a5b","role":"解题依据","why":"行政执法直接关系群众切身利益和法治信心，据此说明提升执法质量的治理意义。"}]}},"terms":{"k-469f06bedb2b5a5f":{"id":"k-469f06bedb2b5a5f","mode":"k","type":"制度与规则","title":"法治中国建设的首要任务","qs":[],"count":2},"k-e69dd9ac0a8d9123":{"id":"k-e69dd9ac0a8d9123","mode":"k","type":"制度与规则","title":"宪法的根本法地位","qs":[],"count":2}},"references":{"govlaw":{"name":"《法治政府建设实施纲要（2021—2025年）》","url":"https://www.mee.gov.cn/zcwj/zyygwj/202108/t20210812_856133.shtml"}},"topics":[{"slug":"law","title":"法治政府与依法行政"}],"units":{"k-c2383a4ccfc99a5b":[["政治理论必刷100题#93"],["政治理论必刷100题#94"],["政治理论必刷100题#95"],["政治理论必刷100题#96"],["江苏 2024 B类 申论#4"]]}};
